import hashlib,pathlib,difflib
ROOT=pathlib.Path(__file__).resolve().parents[1];WORK=ROOT/'work'
def sha(t):return hashlib.sha256(t.encode()).hexdigest()
def write(rel,text):p=WORK/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8',newline='')
def patch(rel,expected,ops):
 p=WORK/rel;t=p.read_text(encoding='utf-8')
 if sha(t)!=expected:raise SystemExit(f'unexpected base {rel}: {sha(t)}')
 l=t.splitlines(keepends=True)
 for a,b,r in sorted(ops,key=lambda x:x[0],reverse=True):l[a:b]=r.splitlines(keepends=True)
 write(rel,''.join(l))
write('public/js/diagnostics.js',"export const DIAGNOSTICS_SCHEMA='cosmic-web-diagnostics-2';\nexport const DIAGNOSTICS_REVISION='privacy-safe-detail-2';\nexport const MAX_DIAGNOSTIC_EVENTS=1200;\nconst BLOCKED_KEY=/key|authorization|cookie|prompt|transcript|audio|filename|email|token|fingerprint|principal|secret|credential/i;\n\nfunction boundedPrimitive(value){\n  if(value===null||typeof value==='boolean')return value;\n  if(typeof value==='number')return Number.isFinite(value)?value:null;\n  if(typeof value==='string')return value.slice(0,300);\n  if(Array.isArray(value))return value.slice(0,32).map(boundedPrimitive).filter(v=>v!==undefined);\n  return undefined;\n}\n\nexport function makeDiagnosticEvent(category,data={}, {now=()=>new Date().toISOString(),elapsedMs=0}={}){\n  const event={time:now(),pageElapsedMs:Math.max(0,Math.round(Number(elapsedMs)||0)),category:String(category||'event').slice(0,80)};\n  for(const [key,value] of Object.entries(data||{})){\n    if(BLOCKED_KEY.test(key))continue;\n    const safe=boundedPrimitive(value);\n    if(safe!==undefined)event[key]=safe;\n  }\n  return event;\n}\n\nexport function pushDiagnostic(events,event,max=MAX_DIAGNOSTIC_EVENTS){\n  if(!Array.isArray(events))throw new TypeError('events must be an array');\n  events.push(event);\n  const limit=Math.max(100,Math.min(5000,Number.isInteger(max)?max:MAX_DIAGNOSTIC_EVENTS));\n  if(events.length>limit)events.splice(0,events.length-limit);\n  return event;\n}\n\nexport function diagnosticErrorFields(error){\n  return {\n    code:typeof error?.code==='string'?error.code:'unknown_error',\n    errorName:typeof error?.name==='string'?error.name:'Error',\n    status:Number.isInteger(error?.status)?error.status:null\n  };\n}\n")
write('public/js/transport-policy.js',"export function classifyTransportFailure(error,{cancelRequested=false,signal=null,online=true}={}){\n  const status=Number.isInteger(error?.status)?error.status:null;\n  const signalAborted=!!signal?.aborted;\n  const userCancelled=!!cancelRequested&&signalAborted;\n  if(userCancelled)return {code:'user_cancelled',userCancelled:true,billingAmbiguous:true,signalAborted:true};\n  if(error?.name==='AbortError')return {code:'browser_transport_abort',userCancelled:false,billingAmbiguous:true,signalAborted};\n  if(!status&&error?.name==='TypeError')return {code:online?'browser_network_error':'browser_offline',userCancelled:false,billingAmbiguous:true,signalAborted};\n  if(!status&&(!error?.code||error.code==='unknown_error'))return {code:online?'browser_transport_error':'browser_offline',userCancelled:false,billingAmbiguous:true,signalAborted};\n  return {code:error?.code||null,userCancelled:false,billingAmbiguous:false,signalAborted};\n}\n\nexport function applyTransportClassification(error,context={}){\n  const classification=classifyTransportFailure(error,context);\n  if(error&&typeof error==='object'){\n    if(classification.code&&(!error.code||error.code==='unknown_error'||classification.userCancelled))error.code=classification.code;\n    error.ctwUserCancelled=classification.userCancelled;\n    error.ctwTransport=classification;\n  }\n  return classification;\n}\n\nexport function isExplicitUserCancellation(error,{cancelRequested=false}={}){\n  return !!cancelRequested||error?.ctwUserCancelled===true||error?.code==='user_cancelled';\n}\n")
